/**
 * Tests for the "Relatórios" page — aba Perdas (Rendimento + Relatório de
 * Produção e Baixas).
 *
 * Covered behavior:
 * - The Rendimento table groups by the MATÉRIA-PRIMA escaneada
 *   (`rawProduct`), never by the product generated by the portioning.
 * - "Peso Total Produzido" / "Total de Etiquetas Produzidas" are FIXED by
 *   the production (the declared outputs): writing labels off (baixa)
 *   only shrinks the "estoque atual" columns — produced 77, wrote off 7
 *   → produced stays 77, stock shows 70.
 * - The "Baixas" checkboxes filter the perda columns: with "Todas as
 *   opções" checked every writeoff counts; clicking one destination
 *   leaves "todas" and excludes only that destination. The individual
 *   checkboxes are always clickable (they used to be disabled while
 *   "Todas as opções" was checked, so the filter could not be changed).
 */
import { describe, it, expect, vi, afterEach } from 'vitest';
import { render, screen, fireEvent, within, cleanup } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { SnackbarProvider } from 'notistack';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';

vi.mock('next/navigation', () => ({
  useRouter: () => ({ push: vi.fn(), replace: vi.fn(), back: vi.fn(), prefetch: vi.fn() }),
  usePathname: () => '/reports',
  useSearchParams: () => new URLSearchParams(),
}));

vi.mock('@/lib/api', () => {
  const RAW_ID = 'p-raw';
  const OUT_ID = 'p-out';
  const OUT_NAME = 'FRALDINHA RED PARMEGIANA 240g';
  const products = [
    {
      _id: RAW_ID,
      name: 'FRALDINHA RED',
      group: 'Carnes',
      storageMethod: 'Refrigerado',
      shelfLifeDays: 5,
    },
    {
      _id: OUT_ID,
      name: OUT_NAME,
      group: 'Carnes',
      storageMethod: 'Refrigerado',
      shelfLifeDays: 3,
    },
  ];
  // 77 etiquetas produzidas, 70 ainda em estoque — as outras 7 foram
  // baixadas, ou seja: EXCLUÍDAS do estoque (tombstone à parte).
  const stockItems = Array.from({ length: 70 }, (_, i) => ({
    _id: `lbl-${i}`,
    qrCode: `QR87568${i}`,
    product: { productId: OUT_ID, productName: OUT_NAME },
    type: 'portioned',
    status: 'in_stock',
    weightGrams: 250,
    lote: 'L-87568',
    batchId: 'BATCH-PORT-1',
    manipulationDate: '2026-11-18',
    expiryDate: '2026-11-25',
  }));
  // As 7 baixas da mesma produção: 3 por "Perda", 4 por "ERRO GARÇOM".
  const exit = (id: string, destination: string) => ({
    _id: id,
    product: { productId: OUT_ID, productName: OUT_NAME },
    movementType: 'exit',
    itemType: 'portioned',
    quantity: 1,
    weightGrams: 250,
    reason: `Baixar — ${destination}`,
    destination,
    lote: 'L-87568',
    date: '2026-11-18T00:00:00.000Z',
  });
  const movements = [
    ...[0, 1, 2].map((i) => exit(`mv-perda-${i}`, 'Perda')),
    ...[0, 1, 2, 3].map((i) => exit(`mv-erro-${i}`, 'ERRO GARÇOM')),
  ];
  const portionings = [
    {
      _id: 'pt1',
      product: { productId: OUT_ID, productName: OUT_NAME },
      rawProduct: { productId: RAW_ID, productName: 'FRALDINHA RED' },
      outputs: [
        {
          productId: OUT_ID,
          productName: OUT_NAME,
          portionsCount: 77,
          portionWeightGrams: 250,
        },
      ],
      rawWeightGrams: 25000,
      cleanWeightGrams: 19250,
      lossGrams: 5750,
      date: '2026-11-18T00:00:00.000Z',
      lote: 'L-87568',
      batchId: 'BATCH-PORT-1',
      supplier: 'FRILARA',
    },
  ];
  const destinations = [
    { _id: 'd1', name: 'ERRO GARÇOM', type: 'writeoff', active: true },
  ];
  return {
    default: {
      get: vi.fn((url: string) => {
        if (url === '/products') return Promise.resolve({ data: products });
        if (url === '/stock-items') return Promise.resolve({ data: stockItems });
        if (url === '/stock-movements') return Promise.resolve({ data: movements });
        if (url === '/portionings') return Promise.resolve({ data: portionings });
        if (url === '/movement-destinations')
          return Promise.resolve({ data: destinations });
        return Promise.resolve({ data: [] });
      }),
      post: vi.fn(),
      put: vi.fn(),
      delete: vi.fn(),
    },
  };
});

import ReportsPage from './page';

function renderPage() {
  const queryClient = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  });
  return render(
    <QueryClientProvider client={queryClient}>
      <LocalizationProvider dateAdapter={AdapterDayjs} adapterLocale="pt-br">
        <SnackbarProvider>
          <ReportsPage />
        </SnackbarProvider>
      </LocalizationProvider>
    </QueryClientProvider>,
  );
}

describe('Relatórios — aba Perdas', () => {
  afterEach(cleanup);

  it('Rendimento agrupa pela matéria-prima escaneada (rawProduct)', async () => {
    renderPage();
    const heading = await screen.findByText('Rendimento');
    const card = heading.parentElement!;
    // A linha mostra o produto ESCANEADO (matéria-prima)…
    expect(within(card).getByRole('cell', { name: 'FRALDINHA RED' })).toBeTruthy();
    // …e NUNCA o produto gerado pelo porcionamento.
    expect(
      within(card).queryByRole('cell', { name: 'FRALDINHA RED PARMEGIANA 240g' }),
    ).toBeNull();
  });

  it('produzido é fixo pela produção; baixa só muda o estoque', async () => {
    renderPage();
    // Produziu 77 (declarado no porcionamento), baixou 7, estoque 70.
    expect(await screen.findByText(/Produzido: 77 etiqueta\(s\) \(19250g\)/)).toBeTruthy();
    expect(screen.getByText(/Em estoque: 70 etiqueta\(s\) \(17500g\)/)).toBeTruthy();
  });

  it('as caixas de baixa filtram as colunas de perda', async () => {
    renderPage();
    // "Todas as opções" (padrão): 3 por "Perda" + 4 por "ERRO GARÇOM" = 7.
    expect(await screen.findByText(/Perdido: 7 porção\(ões\) \(1750g\)/)).toBeTruthy();

    // Clicar num destino com "Todas as opções" marcada exclui SÓ aquele
    // destino (antes as caixas ficavam desabilitadas e o clique não fazia
    // nada — o filtro nunca mudava).
    fireEvent.click(screen.getByLabelText('ERRO GARÇOM'));
    expect(await screen.findByText(/Perdido: 3 porção\(ões\) \(750g\)/)).toBeTruthy();
    expect((screen.getByLabelText('Todas as opções') as HTMLInputElement).checked).toBe(false);

    // O total produzido não depende do filtro de baixa.
    expect(screen.getByText(/Produzido: 77 etiqueta\(s\) \(19250g\)/)).toBeTruthy();
  });
});
